package sssm.dev.sssm_backend.a11_inventory.item_type.service;
import java.util.*; import sssm.dev.sssm_backend.a11_inventory.item_type.entity.ItemType; import sssm.dev.sssm_backend.a11_inventory.item_type.repository.*;
public class ItemTypeService { private final ItemTypeDAO dao=new ItemTypeDAOImpl(); public List<ItemType> findAll(Optional<String> q,Optional<Integer> p,Optional<Integer> s){int page=p.orElse(1),size=s.orElse(10);return q.isPresent()?dao.search(q.get(),page,size):dao.findAll(page,size);} public Optional<ItemType> findById(String id){return dao.findById(id);} public ItemType create(ItemType v){return dao.create(v);} public ItemType update(String id,ItemType v){if(dao.findById(id).isEmpty())throw new IllegalArgumentException("ItemType not found with ID: "+id);v.setId(id);return dao.update(v);} public void delete(String id){dao.delete(id);} }
